import re

KEY = re.compile(r"^\s*(?P<key>[\w$]+|'[^']*'|\"[^\"]*\"):\s*(?P<rest>.*?)\s*$")
CLOSE = re.compile(r'^[\]}],?$')
INLINE = re.compile(r'^\[(?P<body>.*)\],?$')

def unq(s):
    s = s.strip()
    if s.endswith(','):
        s = s[:-1].rstrip()
    if len(s) >= 2 and s[0] == s[-1] and s[0] in '\'"':
        s = s[1:-1]
    return s

def parse(lines):
    stack = []
    kv = []
    kvl = []
    items = []
    itl = []
    skip = []

    def sec():
        return '.'.join(n for t, n in stack if t == 'obj' and n)

    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        if CLOSE.match(s):
            if stack:
                stack.pop()
            skip.append(i)
            continue
        if s in ('{', '['):
            stack.append(('obj' if s == '{' else 'arr', ''))
            skip.append(i)
            continue
        m = KEY.match(l)
        if m:
            k = unq(m.group('key'))
            r = m.group('rest')
            if r == '{':
                stack.append(('obj', k))
                kvl.append(i)
                continue
            if r == '[':
                stack.append(('arr', k))
                itl.append(i)
                continue
            mi = INLINE.match(r)
            if mi:
                itl.append(i)
                for part in mi.group('body').split(','):
                    v = unq(part)
                    if v:
                        items.append({'section': sec(), 'list': k, 'item': v})
                continue
            kv.append({'section': sec(), 'key': k, 'value': unq(r)})
            kvl.append(i)
            continue
        if stack and stack[-1][0] == 'arr':
            items.append({'section': sec(), 'list': stack[-1][1], 'item': unq(s)})
            itl.append(i)
            continue
    blocks = []
    if kvl:
        blocks.append({'name': 'config_variables', 'kind': 'table', 'lines': kvl, 'records': kv})
    if itl:
        blocks.append({'name': 'list_items', 'kind': 'table', 'lines': itl, 'records': items})
    return {'blocks': blocks, 'skip': skip}
